let lastTs=-1, acc=0, wheelAng=0;
function frame(ts){
  requestAnimationFrame(frame);
  const now=ts/1000;
  let rdt = lastTs<0 ? 0.016 : now-lastTs;
  lastTs=now;
  if (!(rdt>0) || rdt>0.25) rdt=0.016;
  if (world.state==='running'){
    acc+=rdt;
    let n=0;
    while (acc>=world.dt && n<14){ stepPhysics(world); acc-=world.dt; n++; }
    if (n===14) acc=0;
    /* consume FX events */
    let big=0;
    for (const ev of world.events){
      if (ev.type==='first'){ big=1; for (let i=0;i<26;i++) spawnHit({x:ev.x,y:ev.y,mag:55,nx:ev.nx,ny:ev.ny}); thud(900,true); }
      else { spawnHit(ev); if (ev.mag>60) thud(ev.mag,false); }
    }
    world.events.length=0;
    if (!world.braking) wheelAng -= world.car.vx/0.34*rdt;
  }
  updateFx(rdt, world);
  render(rdt);
  updateHud();
}

